class DynamicResource {
    int* ptr;
    size_t length;
public:
    // Standard constructor allocates resource
    explicit DynamicResource(size_t s) : ptr(new int[s]), length(s) {}
    ~DynamicResource() { delete[] ptr; }

    // Rvalue reference (&&) argument
    DynamicResource(DynamicResource&& source) noexcept
        // 1. Transfer/Steal resource pointers
        : ptr(source.ptr), length(source.length)
    {
        // 2. Neutralize source object
        source.ptr = nullptr;
        source.length = 0;
    }
};
